def is_prime(n):
    if not isinstance(n, int) or n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_balanced(s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or mapping[char] != stack.pop():
                return False

    return not stack


# Test cases
print(is_balanced("((()))"))  # True
print(is_balanced("(()"))  # False
print(is_balanced("({[]})"))  # True
print(is_balanced("({[})"))  # False
